"""Edit embedding lookup, updates and transfer while preserving derivations."""
from pathlib import Path
import sys
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'tools'))
from edit_chapter import load,save,transform
paragraphs={
'Для $K$ categories embedding':r'''Для $K$ категорий обучаемая таблица векторных представлений (embedding) $E\in\mathbb R^{K\times d}$ возвращает строку $e_c$ категории $c$. Математически выбор строки равен $E^\top u_c$, где $u_c$ — столбец one-hot, но реализация может сразу прочитать нужную строку. Обучаются $Kd$ параметров: при $K=10\,000,d=16$ это 160 000 чисел, или 0.64 MB для весов float32 без состояния оптимизатора.''',
'Несколько fields обычно имеют':r'''Разные поля обычно имеют собственные словари и таблицы: город с ID 7 и телефон с ID 7 не являются одним объектом. Выбранные векторы объединяют или передают в другие блоки модели. Размерность $d$ — выбираемый параметр: её увеличение повышает выразительность, но не добавляет наблюдений редкой категории.''',
'Рассмотрим микро-модель со словарём':'''Рассмотрим таблицу на 1000 ID с размерностью 4. ID 42 и 105 выбирают строки (0.1,−0.5,0.8,0.2) и (0.3,0.1,−0.2,0.9); на выходе получается матрица 2×4. Выбор строк сам по себе не смешивает информацию между категориями. Два табличных поля не становятся последовательностью только потому, что им назначены ID.''',
'После Transformer block при обсуждении':'''В текстовой модели исходный вектор токена также извлекают из таблицы. После последующего блока обработки состояние позиции может зависеть от остальных токенов и маски: это уже контекстное состояние, а не исходная статическая строка таблицы. Чтобы изучить табличные представления в этой главе, знать устройство такого блока не требуется; оно разбирается отдельно в основах языковых моделей.''',
'Для batch (пакет примеров) из B строк':r'''Для пакета из $B$ строк одного поля ID имеют форму $B$, результат выбора строк — $B\times d$, а таблица — $K\times d$. Для $F$ полей с размерностями $d_1,\ldots,d_F$ объединение векторов имеет форму $B\times\sum_f d_f$. Дополнение до общей длины (padding), маска и объединение элементов нужны для наборов или последовательностей; одному категориальному значению искусственный PAD не нужен.''',
'Для одного field и scalar linear head':r'''Для одного поля и линейного скалярного выхода предсказание равно $v^\top e_c+b$. При $d=1$ и ненулевом $v$ можно выразить произвольный коэффициент каждой категории, выбрав $e_c=(a_c-b)/v$. Поэтому замена $K$ one-hot коэффициентов на $K$ одномерных представлений сама по себе не ограничивает класс скалярных функций. Значение имеют регуляризация, разделение параметров и последующие блоки.''',
'При M outputs с общей линейной head':r'''Для $M$ выходов и общей линейной головы $H$ размера $d\times M$ матрица эффектов категорий $W=EH$ имеет ранг не выше $d$. Теперь малая размерность связывает разные выходы. Матрица для трёх категорий и двух выходов со строками (1,0), (0,1), (1,1) имеет ранг 2: при $d=1$ её точно не воспроизвести, а $d=2$ достаточно. При отдельном смещении каждого выхода ограничение относится к эффектам после вычитания смещения.''',
'Если далее идёт nonlinear MLP':'''Если дальше стоит нелинейная сеть, ограничение ранга линейной матрицы W уже не описывает всю функцию. Объединение векторов с одной линейной головой остаётся аддитивным по полям. Например, XOR двух бинарных полей нельзя выразить порогом суммы двух независимых эффектов: нужны взаимодействие, нелинейность или другой способ. Сам выбор строк таблицы взаимодействие не создаёт.''',
'Пусть scalar predictor':r'''Пусть скалярный прогноз $\widehat y=v^\top e_c+b$, а функция потерь $L=\tfrac12(\widehat y-y)^2$. По правилу цепочки:''',
'В этом example только выбранная row':'''В этом примере градиент от данных получает выбранная строка таблицы. В пакете вклады всех обращений к одной строке складываются. Однако регуляризация или состояние оптимизатора могут менять и другие параметры, поэтому утверждение «невыбранные строки никогда не меняются» слишком сильное.''',
'Числа: $e_A=':r'''Возьмём $e_A=(1,2)$, $v=(0.5,-1)$, $b=0$, $y=0$. Прогноз равен −1.5, градиент выбранного вектора — (−0.75,1.5). При шаге обучения 0.1 и обновлении только вектора получаем (1.075,1.85), новый прогноз −1.3125 и уменьшение потерь с 1.125 до 0.861328125. Одновременное обновление головы даст другой результат; его разберём ниже.''',
'Пусть row $e_c$ трактуется':r'''Пусть $e_c$ — столбец, а $g_i$ — пришедший градиент при обращении к таблице в позиции $i$. Тогда все обращения к одной категории накапливаются:''',
'Это scatter-add:':r'''Такая операция называется scatter-add: несколько обращений к одному ID добавляются к градиенту одной строки. Если функция потерь уже усреднена по $B$ примерам, пришедшие градиенты уже содержат множитель $1/B$ и повторно делить их нельзя. При масках знаменатель определяется формулой потерь, а не просто числом позиций дополненного массива.''',
'Row A получает сумму':'''Строка A получает сумму двух разных ошибок, а не градиент только последней встречи. Некоторые реализации дополнительно делят градиент на частоту ID: это отдельное правило обновления, а не градиент исходной средней функции потерь. Такую настройку нельзя включать незаметно и считать прежний ручной вывод неизменным.''',
'Для predictor раздела 2 возьмём':r'''Для предыдущей модели возьмём пакет A,A,B: $e_A=(1,2)$, $e_B=(-1,0)$, $v=(0.5,-1)$, метки (0,1,−1). Прогнозы равны −1.5,−1.5,−0.5, а ошибки — −1.5,−2.5,0.5. Для среднего значения половины квадрата ошибки градиенты равны''',
'Entity embeddings выучивают':'''Представления категорий обучаются под конкретную цель, а не создают универсальную смысловую карту. Если цель — кликабельность рекламы, близкие векторы городов могут отражать рекламное поведение, а не географическую близость. Для другой задачи такая геометрия может быть неуместна.''',
'Representation не единственно идентифицируема':r'''Представление не определяется единственным образом: для обратимой матрицы $A$ можно заменить векторы на $Ae_c$, а веса линейной головы на $A^{-\top}v$ и сохранить предсказания. При этом евклидовы расстояния могут измениться. Интерпретация геометрии требует учитывать архитектуру, ограничения и регуляризацию.''',
'Практически геометрия всё же':'''Геометрия может быть полезной: похожие задачи и регуляризация способствуют разделению информации, а ближайшие соседи иногда имеют понятную структуру. Но это проверяют на конкретной последующей задаче или поиске. Красивая двумерная проекция не доказывает полезность исходных расстояний: проекция может их искажать.''',
'Embeddings можно freeze и передать':'''Векторы можно заморозить и передать другой модели, в том числе бустингу. Но если их предварительно обучили на метках всего набора до перекрёстной проверки, полученные признаки уже содержат информацию внешней проверки. Кодировщик должен обучаться внутри разрешённой обучающей части либо быть независимо предобучен в рамках объявленного протокола.''',
'Если embedding используется как generated feature':'''Если представление используют как признак для второй модели, кодировщик становится ещё одним этапом обучения по меткам. Можно обучить его на всей разрешённой внешней обучающей части и передать полученные представления второй модели, но она увидит признаки тех же объектов, на которых обучался кодировщик: это допускает запоминание и отличие от новых данных. Для вневыборочного поведения нужно перекрёстное вычисление с учётом согласования координат ниже. Использование внешних проверочных или тестовых меток при обучении кодировщика до оценки второй модели является утечкой.''',
'У independently trained folds latent axes':'''Оси независимо обученных кодировщиков в разных folds могут поворачиваться, менять масштаб и переставляться. Например, категория A может получить (1,0) в одном fold и (0,1) в другом при согласованных головах и одинаковых прогнозах. Склеивание таких координат в одну OOF-матрицу создаёт несогласованное пространство для второй модели. Это отличается от OOF-вероятности фиксированного положительного класса, смысл которой одинаков на всех folds.''',
'Возможны разные явные решения':'''Возможные решения: общий заранее замороженный независимый кодировщик; выходы модели с фиксированным смыслом вместо скрытых координат; отдельная последующая модель для каждого кодировщика с объединением прогнозов; согласование по опорным объектам из разрешённых данных. Ни один вариант не следует автоматически из самого перекрёстного вычисления. Например, выравнивание Прокруста исправляет ортогональные повороты при подходящих опорных объектах, но не гарантирует согласования произвольных нелинейных представлений и не разрешает использовать проверочные метки.'''
}
def op(t):
 for prefix,replacement in paragraphs.items():
  a=t.find(prefix)
  if a<0:raise ValueError('Missing paragraph: '+prefix)
  ends=[i for i in (t.find('\n\n',a),t.find('\n<!-- EDIT:',a),t.find('\n<!-- /EDIT:',a)) if i>=0]
  if not ends:raise ValueError('Missing boundary: '+prefix)
  b=min(ends);t=t[:a]+replacement+t[b:]
 return t
c=load();transform('01-data-features/02-features/feat-embeddings.md',op,
 'Пакет 03: редактура выбора строк, градиентов, геометрии и переноса; исходные расчёты сохранены, приёмка ожидается.',c);save(c)
print('Embedding lookup, gradients and transfer edited; review remains open.')
